/**
 * Firebase Cloud Messaging background service worker (Phase B2/B5).
 *
 * SOURCE FILE — edit this one, never public/firebase-messaging-sw.js
 * directly. resources/build/generate-firebase-sw.js substitutes the
 * __VITE_FIREBASE_*__ placeholders below with the real values from
 * .env and writes the result to public/firebase-messaging-sw.js, which
 * is what the browser actually loads. That generated file is
 * gitignored (never committed, so a placeholder or a stale value can
 * never accidentally ship) and is regenerated by `npm run build` (and
 * `npm run dev`) — see package.json.
 *
 * ONE authoritative source: the SAME .env VITE_FIREBASE_* values that
 * resources/js/push-notifications.js reads via import.meta.env also
 * drive this file, via the generator script — never two independently
 * maintained copies (Phase B5's review of the B2 duplication concern).
 * A plain static file under public/ still can't read Vite/.env values
 * at request time, which is why generation, not a runtime import,
 * is the mechanism.
 *
 * Uses the COMPAT SDK loaded via importScripts() rather than the
 * modular npm package the rest of the app bundle uses (see
 * resources/js/push-notifications.js) — a classic (non-module) service
 * worker, registered with no special options, cannot `import` an ES
 * module or the npm package graph. This is Firebase's own long-
 * documented pattern for firebase-messaging-sw.js and works reliably
 * across every browser that supports FCM web push, rather than
 * depending on newer, less consistently supported module-worker
 * registration. Correctness here matters more than syntax consistency
 * with the rest of the app bundle — see the Phase B2 report.
 */
importScripts('https://www.gstatic.com/firebasejs/12.19.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/12.19.0/firebase-messaging-compat.js');

firebase.initializeApp({
    apiKey: '__VITE_FIREBASE_API_KEY__',
    authDomain: '__VITE_FIREBASE_AUTH_DOMAIN__',
    projectId: '__VITE_FIREBASE_PROJECT_ID__',
    storageBucket: '__VITE_FIREBASE_STORAGE_BUCKET__',
    messagingSenderId: '__VITE_FIREBASE_MESSAGING_SENDER_ID__',
    appId: '__VITE_FIREBASE_APP_ID__',
});

const messaging = firebase.messaging();

const DEFAULT_ACTION_URL = '/';

/**
 * Duplicated from resources/js/push-notifications.js rather than shared
 * — this file loads as a classic script (importScripts, no ES module
 * import) and cannot import from the app bundle. Accepts only an
 * internal relative path beginning with exactly one "/": rejects an
 * absolute URL of any scheme (http/https/javascript/data — none of
 * which start with "/"), a protocol-relative "//host" path, and any
 * whitespace-containing value. Never trusts the push payload blindly.
 */
function sanitizeActionUrl(candidate) {
    if (typeof candidate !== 'string' || candidate.length === 0) {
        return DEFAULT_ACTION_URL;
    }

    if (candidate.charAt(0) !== '/' || candidate.charAt(1) === '/' || /\s/.test(candidate)) {
        return DEFAULT_ACTION_URL;
    }

    return candidate;
}

/**
 * The OS-level notification remains the primary channel — it is what
 * reaches a visitor who doesn't currently have RPPL open at all, which
 * is the actual point of a push notification. It depends entirely on
 * Windows/Chrome settings outside this app's control (Focus Assist,
 * per-origin notification throttling, etc. — see the Phase B5
 * real-device verification), so it can legitimately show nothing with
 * no error even when everything here is correct.
 *
 * In ADDITION, this always relays the payload to every open RPPL tab
 * (regardless of Firebase's own onMessage/onBackgroundMessage focus
 * routing, which proved unreliable in local testing) — the page decides
 * for itself whether it's actually visible and shows a guaranteed,
 * in-page confirmation (SweetAlert) only in that case. See
 * push-notifications.js's service-worker message listener.
 */
messaging.onBackgroundMessage((payload) => {
    const title = payload?.notification?.title ?? 'RPPL';
    const body = payload?.notification?.body ?? '';
    const actionUrl = sanitizeActionUrl(payload?.data?.action_url);

    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
        clients.forEach((client) => client.postMessage({ type: 'RPPL_PUSH_RECEIVED', title, body, actionUrl }));
    });

    // Returning the showNotification() promise (rather than firing it and
    // letting the callback return undefined) lets Firebase's own
    // onBackgroundMessage wrapper keep the service worker alive until it
    // actually finishes — otherwise the worker can be suspended before
    // the notification is fully shown. No `icon` option: public/
    // favicon.ico is a broken/empty file in this project, and a bad icon
    // URL can make Chrome silently fail to render the notification at
    // all rather than just showing without one — omitting it lets the
    // browser fall back to its own default instead of depending on it.
    return self.registration.showNotification(title, {
        body,
        data: { actionUrl },
    });
});

/**
 * Focuses an already-open same-origin RPPL tab and navigates it to the
 * notification's (already-sanitized) action URL, or opens a new tab if
 * none is open. Never navigates to an external origin — every URL used
 * here is built from the sanitized internal path above, resolved
 * against this service worker's own origin.
 */
self.addEventListener('notificationclick', (event) => {
    event.notification.close();

    const actionUrl = event.notification.data?.actionUrl ?? DEFAULT_ACTION_URL;
    const targetUrl = new URL(actionUrl, self.location.origin).href;

    event.waitUntil(
        self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
            const alreadyOpen = clients.find((client) => client.url === targetUrl);

            if (alreadyOpen) {
                return alreadyOpen.focus();
            }

            const sameOrigin = clients.find((client) => new URL(client.url).origin === self.location.origin);

            if (sameOrigin) {
                return sameOrigin.focus().then((focused) => focused.navigate(targetUrl));
            }

            return self.clients.openWindow(targetUrl);
        }),
    );
});
